from taf.sbts.oam.sc.rest.schemas.base import SchemaField, SchemaObject


class SoftwareInfoSWMV1(SchemaObject):
    sw_version = SchemaField(name="sw_version", not_null=True)
    usage_state = SchemaField(name="usage_state", not_null=True)
    service_type = SchemaField(name="service_type", not_null=True)
    installation_time = SchemaField(name="installation_time", not_null=True)
    activation_time = SchemaField(name="activation_time", optional=True)

    def __init__(self, sw_version=None, usage_state=None, service_type=None, installation_time=None,
                 activation_time=None):
        self.sw_version = sw_version
        self.usage_state = usage_state
        self.service_type = service_type
        self.installation_time = installation_time.strftime(
            "%Y-%m-%dT%H:%M:%S%Z") if installation_time else installation_time
        self.activation_time = activation_time.strftime(
            "%Y-%m-%dT%H:%M:%S%Z") if activation_time else activation_time
        super(SoftwareInfoSWMV1, self).__init__()
